		f.appendKeyValue(b, "level", entry.Level.String())
		if entry.HasCaller() {
			f.appendKeyValue(b, "func", entry.Caller)
		}
		if entry.Message != "" {
			f.appendKeyValue(b, "msg", entry.Message)
		}
		for _, key := range keys {
			f.appendKeyValue(b, key, entry.Data[key])
		}
	}

	b.WriteByte('\n')
	return b.Bytes(), nil
}
